# importing matplotlib modulesimport matplotlib.image as mpimgimport matplotlib.pyplot as pltimport numpy as npimport structimport numpy as npfrom PIL import Imagefilepath_read=r'C:\Users\sandrine.auriol\Downloads\oneTile3.jpg'filepath_write=r'C:\Data\Zemax\IMAFiles\oneTile3.BIM'# Read Images#img = mpimg.imread(filepath_read)# Convert to grey scaleim = np.array(Image.open(filepath_read).convert('L')) #you can pass multiple arguments in single line# plt.imshow(im)# plt.show()size = im.shapeheight = size[0]width = size[1]file = open(filepath_write, "wb") # Overwrites the file if the file exists# width_byte = width.to_bytes((width.bit_length() + 7) // 8, byteorder='little')# height_byte = width.to_bytes((height.bit_length() + 7) // 8, byteorder='little')height_byte = height.to_bytes(4, byteorder='little')width_byte = width.to_bytes(4, byteorder='little')# file.write(width_byte)# file.write(height_byte)if height >= width:    square_size = height    file.write(height_byte)    file.write(height_byte)if width > height:    square_size = width    file.write(width_byte)    file.write(width_byte)for j in range(square_size - 1, 1, -1):    for i in range(0, square_size, 1):        if j >= (height - 1) or i >= width:            file.write(struct.pack('d', 255))        else:            file.write(struct.pack('d', im[j, i]))file.close()